function readToken(port: number): Promise<string> {
  return new Promise((resolve, reject) => {
    const socket = connect({ host: "127.0.0.1", port })
    let buffer = Buffer.alloc(0)
    socket.on("data", chunk => {
      buffer = Buffer.concat([buffer, chunk])
      if (buffer.length < 4) return
      const length = buffer.readUInt32BE(0)
      if (length < 32 || length > 256) {
        socket.destroy()
        reject(new Error("invalid token frame length"))
        return
      }
      if (buffer.length < 4 + length) return
      const token = [REDACTED_CREDENTIAL] 4 + length).toString("ascii")
      buffer.fill(0)
      socket.destroy()
      resolve(token)
    })
    socket.once("error", reject)
    socket.once("close", hadError => {
      if (!hadError && buffer.length > 0 && buffer.length < 4) reject(new Error("truncated token frame"))
    })
  })
}
